package com.slayereta;

/**
 * Works out a kill rate from the times task kills are seen.
 *
 * Time only counts between two kills that are close together. Any gap longer
 * than the break threshold (banking, AFK, walking back) is dropped, so the rate
 * reflects how fast you kill while actually on task, not your downtime.
 */
class KillRateTracker
{
	private static final double MS_PER_HOUR = 3_600_000d;

	private long lastKillMs = -1;
	private long activeMs;
	private int kills;

	/**
	 * Record that {@code count} kills happened at {@code nowMs}.
	 */
	void recordKills(int count, long nowMs, long breakThresholdMs)
	{
		if (count <= 0)
		{
			return;
		}

		if (lastKillMs < 0)
		{
			// The first kill seen only starts the clock. There is no earlier
			// timestamp to measure it against, so it cannot be counted.
			lastKillMs = nowMs;
			return;
		}

		long gap = nowMs - lastKillMs;
		if (gap > 0 && gap <= breakThresholdMs)
		{
			activeMs += gap;
			kills += count;
		}
		// A gap over the threshold is a break: skip that stretch of time and
		// the kill that ended it, and restart the clock from here.
		lastKillMs = nowMs;
	}

	/**
	 * Kills counted towards the rate (excludes clock-starting kills).
	 */
	int getCountedKills()
	{
		return kills;
	}

	/**
	 * Kills per hour, or 0 when there isn't enough data yet.
	 */
	double getKillsPerHour()
	{
		if (kills <= 0 || activeMs <= 0)
		{
			return 0;
		}
		return kills * MS_PER_HOUR / activeMs;
	}

	void reset()
	{
		lastKillMs = -1;
		activeMs = 0;
		kills = 0;
	}
}

package com.slayereta;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(SlayerEtaConfig.GROUP)
public interface SlayerEtaConfig extends Config
{
	String GROUP = "slayertasketa";

	@ConfigItem(
		keyName = "idleThreshold",
		name = "Break threshold",
		description = "A gap between kills longer than this is treated as a break (banking, AFK, travel) and left out of the kill rate",
		position = 1
	)
	@Units(Units.SECONDS)
	@Range(min = 10, max = 1800)
	default int idleThreshold()
	{
		return 120;
	}

	@ConfigItem(
		keyName = "minKills",
		name = "Kills before ETA",
		description = "How many kills to see this session before showing a live rate (a remembered rate from earlier sessions is shown until then)",
		position = 2
	)
	@Range(min = 1, max = 50)
	default int minKills()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "rememberRates",
		name = "Remember rates per task",
		description = "Save your kill rate for each task so the ETA shows straight away next time you get it",
		position = 3
	)
	default boolean rememberRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showFinishTime",
		name = "Show finish clock time",
		description = "Also show the time of day the task should finish",
		position = 4
	)
	default boolean showFinishTime()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showKph",
		name = "Show kills/hr",
		description = "Show your current kill rate",
		position = 5
	)
	default boolean showKph()
	{
		return true;
	}
}

package com.slayereta;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class SlayerEtaOverlay extends OverlayPanel
{
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm");
	private static final Color SAVED_RATE_COLOUR = new Color(200, 200, 120);

	private final SlayerEtaPlugin plugin;
	private final SlayerEtaConfig config;

	@Inject
	SlayerEtaOverlay(SlayerEtaPlugin plugin, SlayerEtaConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String task = plugin.getCurrentTask();
		if (task == null)
		{
			return null;
		}

		int left = plugin.getRemaining();
		double kph = plugin.getEffectiveKph();
		boolean live = plugin.hasLiveRate();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Slayer ETA")
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left(task)
			.right(left + " left")
			.build());

		if (kph <= 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("ETA")
				.right(plugin.getKillsUntilLiveRate() + " more kills")
				.build());
			return super.render(graphics);
		}

		// Colour the numbers differently while still running on a rate
		// remembered from a previous session.
		Color colour = live ? Color.WHITE : SAVED_RATE_COLOUR;

		if (config.showKph())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(live ? "Kills/hr" : "Kills/hr (saved)")
				.right(String.valueOf(Math.round(kph)))
				.rightColor(colour)
				.build());
		}

		long secondsLeft = Math.round(left * 3600d / kph);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("ETA")
			.right(formatDuration(secondsLeft))
			.rightColor(colour)
			.build());

		if (config.showFinishTime())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Done at")
				.right(LocalTime.now().plusSeconds(secondsLeft).format(CLOCK))
				.rightColor(colour)
				.build());
		}

		return super.render(graphics);
	}

	static String formatDuration(long totalSeconds)
	{
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		if (minutes > 0)
		{
			return minutes + "m " + seconds + "s";
		}
		return seconds + "s";
	}
}

package com.slayereta;

import com.google.inject.Provides;
import java.util.Locale;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.slayer.SlayerPlugin;
import net.runelite.client.plugins.slayer.SlayerPluginService;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Slayer Task ETA",
	description = "Shows how long until your current Slayer task is finished, based on your kill rate",
	tags = {"slayer", "eta", "kills", "kph", "timer", "task"}
)
@PluginDependency(SlayerPlugin.class)
public class SlayerEtaPlugin extends Plugin
{
	private static final String RATE_KEY_PREFIX = "kph_";
	private static final int SAVE_EVERY_KILLS = 10;

	@Inject
	private SlayerPluginService slayerService;

	@Inject
	private SlayerEtaConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SlayerEtaOverlay overlay;

	private final KillRateTracker tracker = new KillRateTracker();

	@Getter
	private String currentTask;

	@Getter
	private int remaining;

	/** Rate loaded from a previous session for the current task, or 0. */
	@Getter
	private double savedKph;

	private int lastRemaining = -1;
	private int killsAtLastSave;

	@Provides
	SlayerEtaConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerEtaConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clearTask();
	}

	@Override
	protected void shutDown()
	{
		saveRate();
		overlayManager.remove(overlay);
		clearTask();
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		String task = slayerService.getTask();
		int left = slayerService.getRemainingAmount();

		if (task == null || task.isEmpty() || left <= 0)
		{
			if (currentTask != null)
			{
				saveRate();
				clearTask();
			}
			return;
		}

		if (!task.equalsIgnoreCase(currentTask))
		{
			saveRate();
			startTask(task, left);
			return;
		}

		if (left < lastRemaining)
		{
			tracker.recordKills(lastRemaining - left, System.currentTimeMillis(),
				config.idleThreshold() * 1000L);

			if (tracker.getCountedKills() - killsAtLastSave >= SAVE_EVERY_KILLS)
			{
				saveRate();
			}
		}
		else if (left > lastRemaining)
		{
			// Task count went up (extended, or a fresh assignment of the same
			// monster). Keep the remembered rate but start timing again.
			saveRate();
			tracker.reset();
			killsAtLastSave = 0;
		}

		lastRemaining = left;
		remaining = left;
	}

	/**
	 * The rate the ETA should use: the live rate once there are enough kills
	 * this session, otherwise the remembered rate for this task.
	 */
	double getEffectiveKph()
	{
		if (hasLiveRate())
		{
			return tracker.getKillsPerHour();
		}
		return config.rememberRates() ? savedKph : 0;
	}

	boolean hasLiveRate()
	{
		return tracker.getCountedKills() >= config.minKills() && tracker.getKillsPerHour() > 0;
	}

	int getKillsUntilLiveRate()
	{
		return Math.max(0, config.minKills() - tracker.getCountedKills());
	}

	private void startTask(String task, int left)
	{
		currentTask = task;
		remaining = left;
		lastRemaining = left;
		tracker.reset();
		killsAtLastSave = 0;
		savedKph = loadRate(task);
		log.debug("Tracking task {} ({} left), saved rate {}", task, left, savedKph);
	}

	private void clearTask()
	{
		currentTask = null;
		remaining = 0;
		lastRemaining = -1;
		savedKph = 0;
		killsAtLastSave = 0;
		tracker.reset();
	}

	private void saveRate()
	{
		if (!config.rememberRates() || currentTask == null || !hasLiveRate())
		{
			return;
		}

		double kph = tracker.getKillsPerHour();
		configManager.setRSProfileConfiguration(SlayerEtaConfig.GROUP, rateKey(currentTask),
			String.format(Locale.ROOT, "%.1f", kph));
		savedKph = kph;
		killsAtLastSave = tracker.getCountedKills();
	}

	private double loadRate(String task)
	{
		String value = configManager.getRSProfileConfiguration(SlayerEtaConfig.GROUP, rateKey(task));
		if (value == null)
		{
			return 0;
		}
		try
		{
			return Double.parseDouble(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static String rateKey(String task)
	{
		return RATE_KEY_PREFIX + task.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_");
	}
}

package com.slayereta;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class KillRateTrackerTest
{
	private static final long BREAK_MS = 120_000;

	@Test
	public void firstKillOnlyStartsTheClock()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, BREAK_MS);
		assertEquals(0, t.getCountedKills());
		assertEquals(0, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void steadyKillEvery30sIs120PerHour()
	{
		KillRateTracker t = new KillRateTracker();
		for (int i = 0; i <= 10; i++)
		{
			t.recordKills(1, i * 30_000L, BREAK_MS);
		}
		assertEquals(10, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void breaksAreLeftOutOfTheRate()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, BREAK_MS);
		t.recordKills(1, 30_000, BREAK_MS);
		t.recordKills(1, 60_000, BREAK_MS);
		// 10 minute bank trip
		t.recordKills(1, 660_000, BREAK_MS);
		t.recordKills(1, 690_000, BREAK_MS);
		assertEquals(3, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void multiKillTickCountsEveryKill()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, BREAK_MS);
		t.recordKills(3, 60_000, BREAK_MS);
		assertEquals(3, t.getCountedKills());
		assertEquals(180, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void durationFormatting()
	{
		assertEquals("45s", SlayerEtaOverlay.formatDuration(45));
		assertEquals("12m 5s", SlayerEtaOverlay.formatDuration(725));
		assertEquals("1h 23m", SlayerEtaOverlay.formatDuration(4980));
	}
}

